  // reporter ("ℹ pass N") across Node versions.
  const passMatch = output.match(/(?:#|\u2139)\s*pass\s+(\d+)/);
  const failMatch = output.match(/(?:#|\u2139)\s*fail\s+(\d+)/);
  const totalMatch = output.match(/(?:#|\u2139)\s*tests\s+(\d+)/);
  const passes = passMatch ? Number(passMatch[1]) : 0;
  const fails = failMatch ? Number(failMatch[1]) : (code === 0 ? 0 : 1);
  const total = totalMatch ? Number(totalMatch[1]) : (passes + fails);

  // Genuine acceptance requires: clean process exit, zero reported failures,
  // at least one reported pass, the reported total matching the reported
  // passes (no silently-skipped cases), and the reported total being at
  // least as many as the pinned suite actually defines (no truncated run).
  const accept =
    code === 0 &&
    fails === 0 &&
    passes > 0 &&
    passes === total &&
    total >= expectedTestCount;

  return {
    accept,
    reason: accept
